insert into public.explore_subjects (slug, title, tagline, description, discipline, difficulty, motif, theme, status, tags, featured, trending, emerging, beginner_friendly, university_level, added_at, estimated_hours, learners_exploring, detail, sort_order) values ('robotics-autonomous-systems', 'Robotics & Autonomous Systems', 'Design machines that sense, think and act.', 'Discover how robots perceive the world, plan their movements and act safely alongside people — from factory arms to Mars rovers.', 'Engineering', 'intermediate', 'robot', '{"base":"#1e3a8a","accent":"#60a5fa","tint":"#dbeafe","ink":"#1e40af"}'::jsonb, 'available', array['Mechatronics', 'Control', 'Sensors', 'Programming']::text[], true, true, true, true, true, '2026-10-28', 64, 4820, '{"introduction":"Robotics brings together mechanical engineering, electronics and computer science to create machines that can sense their environment, make decisions and move with purpose. Autonomous systems take this further — operating without constant human control, from self-driving vehicles to warehouse robots and surgical assistants.","applications":[{"title":"Manufacturing","description":"Precise, tireless robotic arms assemble cars, electronics and medical devices."},{"title":"Healthcare","description":"Surgical robots, rehabilitation exoskeletons and hospital logistics."},{"title":"Exploration","description":"Rovers, underwater drones and space robotics reach places humans cannot."},{"title":"Agriculture","description":"Autonomous tractors and harvesting robots support food production."}],"whyItMatters":["Robots are taking on dangerous, repetitive and precise work across every industry.","Autonomous systems raise important questions about safety, ethics and the future of work.","Robotics is one of the best ways to see mathematics, physics and coding working together."],"outcomes":["Explain how sensors, actuators and controllers form a robotic system.","Describe robot motion using coordinates, vectors and transformations.","Program simple control behaviours and test them in simulation.","Plan and present a small autonomous robotics project."],"foundationalKnowledge":["Basic algebra and graphs","Forces and motion","Simple circuits","Logical thinking"],"prerequisites":[{"title":"Forces & motion","why":"Robots move by applying forces and torques.","categorySlug":"science-discovery"},{"title":"Introductory programming logic","why":"Control behaviours are written as programs.","categorySlug":"artificial-intelligence"},{"title":"Making & manufacturing basics","why":"Understanding how mechanical parts are produced.","categorySlug":"manufacturing"}],"stages":[{"id":"rob-s1","academy":"Foundation","title":"How robots work","summary":"Parts of a robot, sensing and simple movement — no prior knowledge needed.","weeks":4},{"id":"rob-s2","academy":"Advanced","title":"Motion, control & programming","summary":"Kinematics, feedback control and writing robot behaviours.","weeks":6},{"id":"rob-s3","academy":"Elite Mastery","title":"Autonomy & projects","summary":"Navigation, mapping and an independent robotics project.","weeks":6}],"durationLabel":"About 16 weeks at 4 hours per week","relatedCategorySlug":"science-discovery","curriculum":{"referenceInstitution":"Illustrative reference — generic undergraduate unit structure","referenceUnitTitle":"Introduction to Robotics Engineering","referenceUnitCode":"ROB-101 (illustrative)","isIllustrative":true,"description":"An introduction to the principles of robotic systems: mechanical structure, sensing, actuation, kinematics, control and autonomy. Learners progress from first principles to a capstone autonomous robotics project.","outcomes":["Identify the subsystems of a robot and explain how they interact.","Apply coordinate transformations to describe robot position and orientation.","Implement feedback control for a simple actuator.","Evaluate approaches to autonomous navigation.","Communicate the design and testing of a robotics project."],"prerequisites":["Algebra and trigonometry","Introductory physics (forces, energy)","Basic programming concepts"],"modules":[{"id":"rob-m1","number":1,"title":"Introduction to Robotics","summary":"What makes a machine a robot, and where robots are used today.","weeks":"Week 1–2","topics":[{"id":"rob-m1-t1","title":"What is a robot?","source":"edumate","durationMins":15},{"id":"rob-m1-t2","title":"A short history of robotics","source":"edumate","durationMins":20},{"id":"rob-m1-t3","title":"Robot safety and ethics","source":"edumate","durationMins":12}],"lectureRefs":["mit-ocw"],"readings":["modern-robotics"]},{"id":"rob-m2","number":2,"title":"Mathematics for Robotics","summary":"Vectors, matrices and trigonometry as the language of motion.","weeks":"Week 3–4","topics":[{"id":"rob-m2-t1","title":"Vectors and coordinate frames","source":"edumate","durationMins":20},{"id":"rob-m2-t2","title":"Rotation matrices","source":"reference","durationMins":12},{"id":"rob-m2-t3","title":"Homogeneous transformations","source":"reference","durationMins":10}],"lectureRefs":["khan-linear-algebra"],"readings":["modern-robotics"]},{"id":"rob-m3","number":3,"title":"Mechanical Systems","summary":"Links, joints, gears and the physical structure of robots.","weeks":"Week 5–6","topics":[{"id":"rob-m3-t1","title":"Links, joints and degrees of freedom","source":"edumate","durationMins":12},{"id":"rob-m3-t2","title":"Gears, torque and power transmission","source":"edumate","durationMins":10},{"id":"rob-m3-t3","title":"Configuration space","source":"reference","durationMins":15}],"lectureRefs":[],"readings":["modern-robotics","openstax-physics-2"]},{"id":"rob-m4","number":4,"title":"Electronics and Sensors","summary":"How robots sense the world and drive motors.","weeks":"Week 7–8","topics":[{"id":"rob-m4-t1","title":"Circuits for robotics","source":"edumate","durationMins":10},{"id":"rob-m4-t2","title":"Sensors: distance, light, touch and IMUs","source":"edumate","durationMins":15},{"id":"rob-m4-t3","title":"Motors, servos and drivers","source":"edumate","durationMins":20}],"lectureRefs":[],"readings":["openstax-physics-2"],"practicalId":"lab-circuit-basics"},{"id":"rob-m5","number":5,"title":"Programming and Control","summary":"Feedback loops that keep robots on target.","weeks":"Week 9–10","topics":[{"id":"rob-m5-t1","title":"Open-loop vs closed-loop control","source":"edumate","durationMins":15},{"id":"rob-m5-t2","title":"PID control","source":"reference","durationMins":20},{"id":"rob-m5-t3","title":"Introduction to ROS","source":"edumate","durationMins":12}],"lectureRefs":["mit-ocw"],"readings":["ros-docs"]},{"id":"rob-m6","number":6,"title":"Robot Kinematics","summary":"Calculating where a robot arm is — and how to get it somewhere.","weeks":"Week 11–12","topics":[{"id":"rob-m6-t1","title":"Forward kinematics","source":"edumate","durationMins":20},{"id":"rob-m6-t2","title":"Denavit–Hartenberg parameters","source":"reference","durationMins":12},{"id":"rob-m6-t3","title":"Inverse kinematics","source":"edumate","durationMins":10}],"lectureRefs":[],"readings":["modern-robotics"],"practicalId":"lab-robot-arm"},{"id":"rob-m7","number":7,"title":"Autonomous Navigation","summary":"Localisation, mapping and path planning.","weeks":"Week 13–14","topics":[{"id":"rob-m7-t1","title":"Path planning algorithms","source":"edumate","durationMins":12},{"id":"rob-m7-t2","title":"Probabilistic localisation","source":"reference","durationMins":10},{"id":"rob-m7-t3","title":"SLAM concepts","source":"reference","durationMins":15}],"lectureRefs":[],"readings":["probabilistic-robotics","ros-docs"]},{"id":"rob-m8","number":8,"title":"Advanced Robotics Projects","summary":"Bring everything together in an independent project.","weeks":"Week 15–16","topics":[{"id":"rob-m8-t1","title":"Project scoping and design","source":"edumate","durationMins":10},{"id":"rob-m8-t2","title":"Testing and iteration","source":"edumate","durationMins":15},{"id":"rob-m8-t3","title":"Presenting your robot","source":"edumate","durationMins":20}],"lectureRefs":[],"readings":[],"practicalId":"lab-line-follower"}],"assessments":[{"title":"Module mastery checks","type":"Mastery quiz","weight":30,"description":"Short adaptive quizzes verify each module before progressing."},{"title":"Robotic arm simulation","type":"Practical","weight":25,"description":"Demonstrate forward kinematics in the virtual lab."},{"title":"Explain-it-back","type":"Written explanation","weight":15,"description":"Explain a control concept in your own words on the blank-page workspace."},{"title":"Capstone robot project","type":"Project","weight":30,"description":"Design, simulate and present an autonomous behaviour."}],"furtherStudy":["mit-ocw","probabilistic-robotics","ros-docs"]}}'::jsonb, 0) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, description = excluded.description, discipline = excluded.discipline, difficulty = excluded.difficulty, motif = excluded.motif, theme = excluded.theme, status = excluded.status, tags = excluded.tags, featured = excluded.featured, trending = excluded.trending, emerging = excluded.emerging, beginner_friendly = excluded.beginner_friendly, university_level = excluded.university_level, added_at = excluded.added_at, estimated_hours = excluded.estimated_hours, learners_exploring = excluded.learners_exploring, detail = excluded.detail, sort_order = excluded.sort_order;
insert into public.explore_subjects (slug, title, tagline, description, discipline, difficulty, motif, theme, status, tags, featured, trending, emerging, beginner_friendly, university_level, added_at, estimated_hours, learners_exploring, detail, sort_order) values ('artificial-intelligence-machine-learning', 'Artificial Intelligence & Machine Learning', 'Teach computers to learn from data.', 'Understand how machines recognise patterns, make predictions and generate language — and how to build and question AI responsibly.', 'Computing', 'intermediate', 'neural', '{"base":"#4c1d95","accent":"#c4b5fd","tint":"#ede9fe","ink":"#5b21b6"}'::jsonb, 'available', array['Neural networks', 'Data', 'Ethics', 'Python']::text[], true, true, true, true, true, '2026-10-20', 72, 9310, '{"introduction":"Artificial intelligence is the science of making computers perform tasks that normally require human intelligence. Machine learning — its most successful branch today — lets computers improve at tasks by learning patterns from examples rather than following hand-written rules.","applications":[{"title":"Language","description":"Translation, chat assistants and summarisation tools."},{"title":"Medicine","description":"Detecting disease in scans and accelerating drug discovery."},{"title":"Climate","description":"Forecasting weather and optimising energy grids."},{"title":"Science","description":"Predicting protein structures and analysing telescope data."}],"whyItMatters":["AI is reshaping how people work, learn and communicate.","Understanding how AI works helps you use it wisely and spot its limitations.","Building fair and safe AI is one of the defining challenges of this century."],"outcomes":["Explain the difference between rule-based programs and learned models.","Prepare a dataset and train a simple model.","Build and train a basic neural network.","Evaluate models for accuracy, bias and real-world risk."],"foundationalKnowledge":["Percentages and averages","Reading graphs","Basic coordinate geometry","Curiosity about data"],"prerequisites":[{"title":"What is AI?","why":"Builds on the existing AI knowledge category.","categorySlug":"artificial-intelligence"},{"title":"Statistics & probability basics","why":"Models make predictions under uncertainty.","categorySlug":"science-discovery"},{"title":"Digital ethics","why":"Responsible use of AI in society.","categorySlug":"history-society"}],"stages":[{"id":"ai-s1","academy":"Foundation","title":"Thinking with data","summary":"Patterns, predictions and how machines learn — from zero.","weeks":4},{"id":"ai-s2","academy":"Advanced","title":"Models & neural networks","summary":"Regression, classification and training your first network.","weeks":7},{"id":"ai-s3","academy":"Elite Mastery","title":"Modern AI & responsible design","summary":"Transformers, evaluation and an applied AI project.","weeks":7}],"durationLabel":"About 18 weeks at 4 hours per week","relatedCategorySlug":"artificial-intelligence","curriculum":{"referenceInstitution":"Illustrative reference — generic undergraduate unit structure","referenceUnitTitle":"Foundations of Machine Learning","referenceUnitCode":"AIM-110 (illustrative)","isIllustrative":true,"description":"A structured introduction to machine learning covering data, supervised and unsupervised learning, neural networks, modern architectures and responsible AI.","outcomes":["Describe the machine learning workflow from data to deployment.","Train and evaluate supervised learning models.","Explain how neural networks learn through gradient descent.","Critically assess AI systems for bias, safety and societal impact."],"prerequisites":["Algebra","Introductory statistics","Basic programming (Python recommended)"],"modules":[{"id":"ai-m1","number":1,"title":"What is Artificial Intelligence?","summary":"From rule-based systems to learning machines.","weeks":"Week 1–2","topics":[{"id":"ai-m1-t1","title":"Defining intelligence","source":"edumate","durationMins":15},{"id":"ai-m1-t2","title":"A brief history of AI","source":"edumate","durationMins":20},{"id":"ai-m1-t3","title":"Where AI is used today","source":"edumate","durationMins":12}],"lectureRefs":["mit-ocw"],"readings":[]},{"id":"ai-m2","number":2,"title":"Data and Representation","summary":"How the world becomes numbers a computer can learn from.","weeks":"Week 3–4","topics":[{"id":"ai-m2-t1","title":"Features and labels","source":"edumate","durationMins":20},{"id":"ai-m2-t2","title":"Cleaning and splitting data","source":"edumate","durationMins":12},{"id":"ai-m2-t3","title":"Visualising datasets","source":"edumate","durationMins":10}],"lectureRefs":[],"readings":["d2l"]},{"id":"ai-m3","number":3,"title":"Mathematics for Machine Learning","summary":"Vectors, gradients and probability — explained visually.","weeks":"Week 5–6","topics":[{"id":"ai-m3-t1","title":"Vectors and matrices","source":"edumate","durationMins":12},{"id":"ai-m3-t2","title":"Gradients and optimisation","source":"reference","durationMins":10},{"id":"ai-m3-t3","title":"Probability for predictions","source":"edumate","durationMins":15}],"lectureRefs":["khan-linear-algebra"],"readings":["deep-learning-book"]},{"id":"ai-m4","number":4,"title":"Supervised Learning","summary":"Learning from labelled examples.","weeks":"Week 7–8","topics":[{"id":"ai-m4-t1","title":"Linear regression","source":"edumate","durationMins":10},{"id":"ai-m4-t2","title":"Classification","source":"edumate","durationMins":15},{"id":"ai-m4-t3","title":"Overfitting and regularisation","source":"reference","durationMins":20}],"lectureRefs":[],"readings":["d2l"]},{"id":"ai-m5","number":5,"title":"Neural Networks","summary":"Layers of simple units that learn complex patterns.","weeks":"Week 9–10","topics":[{"id":"ai-m5-t1","title":"The artificial neuron","source":"edumate","durationMins":15},{"id":"ai-m5-t2","title":"Backpropagation","source":"reference","durationMins":20},{"id":"ai-m5-t3","title":"Training loops in practice","source":"edumate","durationMins":12}],"lectureRefs":["3b1b-neural-networks"],"readings":["deep-learning-book"],"practicalId":"lab-neural-network"},{"id":"ai-m6","number":6,"title":"Unsupervised Learning","summary":"Finding structure without labels.","weeks":"Week 11–12","topics":[{"id":"ai-m6-t1","title":"Clustering","source":"edumate","durationMins":20},{"id":"ai-m6-t2","title":"Dimensionality reduction","source":"edumate","durationMins":12},{"id":"ai-m6-t3","title":"Anomaly detection","source":"edumate","durationMins":10}],"lectureRefs":[],"readings":["d2l"]},{"id":"ai-m7","number":7,"title":"Modern Architectures","summary":"Convolutional networks, transformers and generative models.","weeks":"Week 13–15","topics":[{"id":"ai-m7-t1","title":"Convolutional networks for images","source":"edumate","durationMins":12},{"id":"ai-m7-t2","title":"The transformer and attention","source":"reference","durationMins":10},{"id":"ai-m7-t3","title":"Generative AI","source":"edumate","durationMins":15}],"lectureRefs":[],"readings":["attention-paper","d2l"]},{"id":"ai-m8","number":8,"title":"Responsible AI Project","summary":"Build, evaluate and critique an applied model.","weeks":"Week 16–18","topics":[{"id":"ai-m8-t1","title":"Bias and fairness","source":"edumate","durationMins":10},{"id":"ai-m8-t2","title":"Evaluating real-world impact","source":"edumate","durationMins":15},{"id":"ai-m8-t3","title":"Capstone project","source":"edumate","durationMins":20}],"lectureRefs":[],"readings":["pytorch-docs"],"practicalId":"lab-image-classifier"}],"assessments":[{"title":"Module mastery checks","type":"Mastery quiz","weight":30,"description":"Adaptive quizzes confirm understanding of each module."},{"title":"Neural network lab","type":"Practical","weight":25,"description":"Train a small network and report its accuracy."},{"title":"AI ethics explanation","type":"Written explanation","weight":15,"description":"Analyse the risks of a real AI application."},{"title":"Applied AI capstone","type":"Project","weight":30,"description":"Build and evaluate a model on an open dataset."}],"furtherStudy":["deep-learning-book","attention-paper","mit-ocw"]}}'::jsonb, 1) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, description = excluded.description, discipline = excluded.discipline, difficulty = excluded.difficulty, motif = excluded.motif, theme = excluded.theme, status = excluded.status, tags = excluded.tags, featured = excluded.featured, trending = excluded.trending, emerging = excluded.emerging, beginner_friendly = excluded.beginner_friendly, university_level = excluded.university_level, added_at = excluded.added_at, estimated_hours = excluded.estimated_hours, learners_exploring = excluded.learners_exploring, detail = excluded.detail, sort_order = excluded.sort_order;
insert into public.explore_subjects (slug, title, tagline, description, discipline, difficulty, motif, theme, status, tags, featured, trending, emerging, beginner_friendly, university_level, added_at, estimated_hours, learners_exploring, detail, sort_order) values ('energy-generation-storage', 'Energy Generation & Storage', 'Power the world — and keep the lights on.', 'Explore how electricity is generated from sun, wind and atoms, and how batteries and grids store and deliver it reliably.', 'Energy & Environment', 'beginner', 'battery', '{"base":"#065f46","accent":"#6ee7b7","tint":"#d1fae5","ink":"#047857"}'::jsonb, 'available', array['Batteries', 'Renewables', 'Grids', 'Electrochemistry']::text[], true, true, false, true, true, '2026-11-02', 56, 3640, '{"introduction":"Modern life runs on energy. This subject explains where our energy comes from, how it is converted into electricity, and how technologies like lithium-ion batteries and pumped hydro store it for when it is needed — the key challenge of a renewable-powered world.","applications":[{"title":"Electric vehicles","description":"Battery packs, charging and energy efficiency on the road."},{"title":"Renewable grids","description":"Balancing solar and wind with storage and demand."},{"title":"Portable electronics","description":"Making phones and laptops last longer and charge faster."},{"title":"Off-grid power","description":"Bringing reliable electricity to remote communities."}],"whyItMatters":["The energy transition is one of the largest engineering projects in human history.","Storage is the missing piece that makes renewable power reliable.","Energy literacy helps people make better choices at home and in society."],"outcomes":["Compare energy sources by output, cost and environmental impact.","Explain how a battery stores and releases energy.","Model charging and discharging behaviour.","Propose a storage solution for a real-world energy scenario."],"foundationalKnowledge":["Units and measurement","Energy and power","Simple circuits","Reading graphs"],"prerequisites":[{"title":"Energy & power","why":"The core quantities used throughout the subject.","categorySlug":"science-discovery"},{"title":"Chemical reactions","why":"Batteries store energy chemically.","categorySlug":"science-discovery"},{"title":"Energy economics","why":"Cost shapes which technologies are deployed.","categorySlug":"economics"}],"stages":[{"id":"en-s1","academy":"Foundation","title":"Energy all around us","summary":"Forms of energy, power and where electricity comes from.","weeks":3},{"id":"en-s2","academy":"Advanced","title":"Generation & batteries","summary":"Renewable generation and how batteries work inside.","weeks":6},{"id":"en-s3","academy":"Elite Mastery","title":"Grid-scale systems","summary":"Storage design, grid balancing and a system-design project.","weeks":5}],"durationLabel":"About 14 weeks at 4 hours per week","relatedCategorySlug":"science-discovery","curriculum":{"referenceInstitution":"Illustrative reference — generic undergraduate unit structure","referenceUnitTitle":"Energy Systems and Storage Technologies","referenceUnitCode":"ENR-120 (illustrative)","isIllustrative":true,"description":"Fundamentals of energy conversion, renewable generation and electrochemical storage, culminating in the design of an integrated energy system.","outcomes":["Apply energy and power calculations to real systems.","Explain the operating principles of major generation technologies.","Describe the electrochemistry of lithium-ion cells.","Design a storage system for a given demand profile."],"prerequisites":["Introductory physics","Introductory chemistry","Algebra"],"modules":[{"id":"en-m1","number":1,"title":"Energy Fundamentals","summary":"Energy, power and efficiency explained from zero.","weeks":"Week 1–2","topics":[{"id":"en-m1-t1","title":"Forms of energy","source":"edumate","durationMins":15},{"id":"en-m1-t2","title":"Power vs energy","source":"edumate","durationMins":20},{"id":"en-m1-t3","title":"Efficiency and losses","source":"edumate","durationMins":12}],"lectureRefs":[],"readings":["without-hot-air"]},{"id":"en-m2","number":2,"title":"Generating Electricity","summary":"Turbines, generators and the power station.","weeks":"Week 3–4","topics":[{"id":"en-m2-t1","title":"Electromagnetic induction","source":"edumate","durationMins":20},{"id":"en-m2-t2","title":"Thermal power stations","source":"edumate","durationMins":12},{"id":"en-m2-t3","title":"Capacity factor","source":"reference","durationMins":10}],"lectureRefs":[],"readings":["openstax-physics-2"]},{"id":"en-m3","number":3,"title":"Renewable Generation","summary":"Solar, wind, hydro and their variability.","weeks":"Week 5–6","topics":[{"id":"en-m3-t1","title":"Solar photovoltaics","source":"edumate","durationMins":12},{"id":"en-m3-t2","title":"Wind energy","source":"edumate","durationMins":10},{"id":"en-m3-t3","title":"Hydro and marine power","source":"edumate","durationMins":15}],"lectureRefs":[],"readings":["iea-reports","without-hot-air"]},{"id":"en-m4","number":4,"title":"Electrochemistry","summary":"The chemistry that makes batteries possible.","weeks":"Week 7–8","topics":[{"id":"en-m4-t1","title":"Oxidation and reduction","source":"edumate","durationMins":10},{"id":"en-m4-t2","title":"Electrochemical cells","source":"reference","durationMins":15},{"id":"en-m4-t3","title":"Electrode materials","source":"edumate","durationMins":20}],"lectureRefs":[],"readings":["openstax-chemistry-2e"]},{"id":"en-m5","number":5,"title":"Battery Technology","summary":"Inside a lithium-ion cell.","weeks":"Week 9–10","topics":[{"id":"en-m5-t1","title":"How lithium-ion cells work","source":"edumate","durationMins":15},{"id":"en-m5-t2","title":"Charging and discharging","source":"edumate","durationMins":20},{"id":"en-m5-t3","title":"Degradation and lifespan","source":"reference","durationMins":12}],"lectureRefs":[],"readings":["li-ion-perspective","battery-university"],"practicalId":"lab-battery-model"},{"id":"en-m6","number":6,"title":"Beyond Batteries","summary":"Pumped hydro, hydrogen, thermal and mechanical storage.","weeks":"Week 11","topics":[{"id":"en-m6-t1","title":"Pumped hydro storage","source":"edumate","durationMins":20},{"id":"en-m6-t2","title":"Hydrogen as an energy carrier","source":"edumate","durationMins":12},{"id":"en-m6-t3","title":"Thermal and mechanical storage","source":"edumate","durationMins":10}],"lectureRefs":[],"readings":["iea-reports"]},{"id":"en-m7","number":7,"title":"Grids and Integration","summary":"Keeping supply and demand in balance.","weeks":"Week 12–13","topics":[{"id":"en-m7-t1","title":"How the grid works","source":"edumate","durationMins":12},{"id":"en-m7-t2","title":"Frequency and balancing","source":"reference","durationMins":10},{"id":"en-m7-t3","title":"Smart grids","source":"edumate","durationMins":15}],"lectureRefs":[],"readings":["iea-reports"]},{"id":"en-m8","number":8,"title":"Energy System Design Project","summary":"Design a storage solution for a community.","weeks":"Week 14","topics":[{"id":"en-m8-t1","title":"Demand profiles","source":"edumate","durationMins":10},{"id":"en-m8-t2","title":"Sizing storage","source":"edumate","durationMins":15},{"id":"en-m8-t3","title":"Presenting your design","source":"edumate","durationMins":20}],"lectureRefs":[],"readings":[],"practicalId":"lab-microgrid"}],"assessments":[{"title":"Module mastery checks","type":"Mastery quiz","weight":30,"description":"Confirm understanding before progressing."},{"title":"Battery modelling lab","type":"Practical","weight":25,"description":"Model charge/discharge curves in the virtual lab."},{"title":"Energy explainer","type":"Written explanation","weight":15,"description":"Explain the storage challenge to a younger learner."},{"title":"Community microgrid design","type":"Project","weight":30,"description":"Size generation and storage for a real scenario."}],"furtherStudy":["without-hot-air","iea-reports","mit-ocw"]}}'::jsonb, 2) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, description = excluded.description, discipline = excluded.discipline, difficulty = excluded.difficulty, motif = excluded.motif, theme = excluded.theme, status = excluded.status, tags = excluded.tags, featured = excluded.featured, trending = excluded.trending, emerging = excluded.emerging, beginner_friendly = excluded.beginner_friendly, university_level = excluded.university_level, added_at = excluded.added_at, estimated_hours = excluded.estimated_hours, learners_exploring = excluded.learners_exploring, detail = excluded.detail, sort_order = excluded.sort_order;
insert into public.explore_subjects (slug, title, tagline, description, discipline, difficulty, motif, theme, status, tags, featured, trending, emerging, beginner_friendly, university_level, added_at, estimated_hours, learners_exploring, detail, sort_order) values ('semiconductors-chip-manufacturing', 'Semiconductors & Advanced Chip Manufacturing', 'Billions of switches on a fingernail.', 'Learn how silicon becomes the chips inside every phone and computer — from electrons and transistors to nanometre-scale fabrication.', 'Physical Sciences', 'advanced', 'chip', '{"base":"#0f172a","accent":"#38bdf8","tint":"#e0f2fe","ink":"#0369a1"}'::jsonb, 'available', array['Transistors', 'Lithography', 'Silicon', 'Nanotechnology']::text[], true, false, true, false, true, '2026-11-10', 68, 2210, '{"introduction":"Semiconductors are materials whose electrical behaviour can be precisely controlled. Engineered into transistors — tiny electronic switches — they form the foundation of all modern computing. Advanced chip manufacturing is among the most complex processes humans have ever developed, patterning features thousands of times thinner than a human hair.","applications":[{"title":"Computing","description":"Processors and memory in every digital device."},{"title":"AI hardware","description":"Specialised chips accelerate machine learning."},{"title":"Energy","description":"Power electronics and solar cells are semiconductor devices."},{"title":"Communications","description":"Radio chips connect phones, satellites and networks."}],"whyItMatters":["Chips are strategic to every economy and to scientific progress.","Manufacturing them combines physics, chemistry, optics and precision engineering.","The industry needs many more skilled engineers and technicians."],"outcomes":["Explain conduction in semiconductors and the role of doping.","Describe how a transistor acts as a switch.","Outline the main steps of chip fabrication.","Discuss the limits and future of transistor scaling."],"foundationalKnowledge":["Atoms and electrons","Basic circuits","Powers of ten","Scientific notation"],"prerequisites":[{"title":"Atomic structure","why":"Electron behaviour explains semiconductors.","categorySlug":"science-discovery"},{"title":"Simple circuits","why":"Transistors are circuit components.","categorySlug":"science-discovery"},{"title":"Manufacturing processes","why":"Fabrication is precision manufacturing.","categorySlug":"manufacturing"}],"stages":[{"id":"sc-s1","academy":"Foundation","title":"Electrons & materials","summary":"Conductors, insulators and why silicon is special.","weeks":4},{"id":"sc-s2","academy":"Advanced","title":"Devices & circuits","summary":"Diodes, transistors and logic gates.","weeks":6},{"id":"sc-s3","academy":"Elite Mastery","title":"Fabrication & the frontier","summary":"Lithography, cleanrooms and next-generation chips.","weeks":6}],"durationLabel":"About 16 weeks at 4 hours per week","relatedCategorySlug":"manufacturing","curriculum":{"referenceInstitution":"Illustrative reference — generic undergraduate unit structure","referenceUnitTitle":"Semiconductor Devices and Fabrication","referenceUnitCode":"SEM-210 (illustrative)","isIllustrative":true,"description":"Semiconductor physics, device operation and integrated circuit fabrication, from band theory to extreme ultraviolet lithography.","outcomes":["Explain band structure and carrier transport qualitatively.","Analyse the behaviour of diodes and MOSFETs.","Describe each stage of the fabrication process flow.","Evaluate challenges in continued transistor scaling."],"prerequisites":["Introductory physics","Introductory chemistry","Algebra"],"modules":[{"id":"sc-m1","number":1,"title":"Why Semiconductors Matter","summary":"From vacuum tubes to billions of transistors.","weeks":"Week 1","topics":[{"id":"sc-m1-t1","title":"The digital revolution","source":"edumate","durationMins":15},{"id":"sc-m1-t2","title":"Moore’s law","source":"reference","durationMins":20},{"id":"sc-m1-t3","title":"The global chip industry","source":"edumate","durationMins":12}],"lectureRefs":[],"readings":["moore-1965"]},{"id":"sc-m2","number":2,"title":"Electrons in Materials","summary":"Conductors, insulators and semiconductors.","weeks":"Week 2–3","topics":[{"id":"sc-m2-t1","title":"Atoms and electrons","source":"edumate","durationMins":20},{"id":"sc-m2-t2","title":"Energy bands","source":"reference","durationMins":12},{"id":"sc-m2-t3","title":"Silicon’s crystal structure","source":"edumate","durationMins":10}],"lectureRefs":[],"readings":["openstax-physics-2","openstax-chemistry-2e"]},{"id":"sc-m3","number":3,"title":"Doping and Junctions","summary":"Engineering conductivity on purpose.","weeks":"Week 4–5","topics":[{"id":"sc-m3-t1","title":"n-type and p-type doping","source":"edumate","durationMins":12},{"id":"sc-m3-t2","title":"The p–n junction","source":"edumate","durationMins":10},{"id":"sc-m3-t3","title":"Diodes and LEDs","source":"edumate","durationMins":15}],"lectureRefs":[],"readings":["sze-devices"]},{"id":"sc-m4","number":4,"title":"Transistors","summary":"The switch that built the modern world.","weeks":"Week 6–7","topics":[{"id":"sc-m4-t1","title":"How a MOSFET works","source":"edumate","durationMins":10},{"id":"sc-m4-t2","title":"Threshold voltage","source":"reference","durationMins":15},{"id":"sc-m4-t3","title":"Transistors as switches","source":"edumate","durationMins":20}],"lectureRefs":[],"readings":["sze-devices"],"practicalId":"lab-transistor-switch"},{"id":"sc-m5","number":5,"title":"From Transistors to Logic","summary":"Gates, circuits and processors.","weeks":"Week 8–9","topics":[{"id":"sc-m5-t1","title":"CMOS logic gates","source":"edumate","durationMins":15},{"id":"sc-m5-t2","title":"Building an adder","source":"edumate","durationMins":20},{"id":"sc-m5-t3","title":"Inside a processor","source":"edumate","durationMins":12}],"lectureRefs":["mit-ocw"],"readings":[]},{"id":"sc-m6","number":6,"title":"Wafer Fabrication","summary":"Making ultra-pure silicon wafers.","weeks":"Week 10–11","topics":[{"id":"sc-m6-t1","title":"Crystal growth","source":"edumate","durationMins":20},{"id":"sc-m6-t2","title":"Cleanrooms","source":"edumate","durationMins":12},{"id":"sc-m6-t3","title":"Oxidation and deposition","source":"reference","durationMins":10}],"lectureRefs":["mit-ocw"],"readings":[]},{"id":"sc-m7","number":7,"title":"Lithography and Patterning","summary":"Printing nanometre-scale features.","weeks":"Week 12–14","topics":[{"id":"sc-m7-t1","title":"Photolithography","source":"edumate","durationMins":12},{"id":"sc-m7-t2","title":"Extreme ultraviolet (EUV)","source":"reference","durationMins":10},{"id":"sc-m7-t3","title":"Etching","source":"edumate","durationMins":15}],"lectureRefs":["mit-ocw"],"readings":[]},{"id":"sc-m8","number":8,"title":"The Future of Chips","summary":"3D stacking, new materials and beyond silicon.","weeks":"Week 15–16","topics":[{"id":"sc-m8-t1","title":"Chiplets and 3D integration","source":"edumate","durationMins":10},{"id":"sc-m8-t2","title":"New channel materials","source":"edumate","durationMins":15},{"id":"sc-m8-t3","title":"Research frontier project","source":"edumate","durationMins":20}],"lectureRefs":[],"readings":[]}],"assessments":[{"title":"Module mastery checks","type":"Mastery quiz","weight":30,"description":"Adaptive verification of each module."},{"title":"Transistor switching lab","type":"Practical","weight":25,"description":"Explore switching behaviour in the virtual lab."},{"title":"Process-flow explanation","type":"Written explanation","weight":15,"description":"Describe how a chip is made, step by step."},{"title":"Frontier research brief","type":"Project","weight":30,"description":"Investigate and present an emerging chip technology."}],"furtherStudy":["sze-devices","moore-1965","mit-ocw"]}}'::jsonb, 3) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, description = excluded.description, discipline = excluded.discipline, difficulty = excluded.difficulty, motif = excluded.motif, theme = excluded.theme, status = excluded.status, tags = excluded.tags, featured = excluded.featured, trending = excluded.trending, emerging = excluded.emerging, beginner_friendly = excluded.beginner_friendly, university_level = excluded.university_level, added_at = excluded.added_at, estimated_hours = excluded.estimated_hours, learners_exploring = excluded.learners_exploring, detail = excluded.detail, sort_order = excluded.sort_order;
insert into public.explore_subjects (slug, title, tagline, description, discipline, difficulty, motif, theme, status, tags, featured, trending, emerging, beginner_friendly, university_level, added_at, estimated_hours, learners_exploring, detail, sort_order) values ('sustainable-resources-circular-engineering', 'Sustainable Resources & Circular Engineering', 'Design out waste. Keep materials in use.', 'Investigate where materials come from, where they end up, and how engineers design products and systems that regenerate rather than deplete.', 'Energy & Environment', 'beginner', 'cycle', '{"base":"#3f6212","accent":"#bef264","tint":"#ecfccb","ink":"#4d7c0f"}'::jsonb, 'available', array['Circular economy', 'Life-cycle', 'Materials', 'Policy']::text[], true, true, false, true, false, '2026-11-14', 48, 2980, '{"introduction":"Every product begins as raw materials taken from the Earth. Circular engineering asks how we can keep those materials in use for as long as possible — through better design, repair, reuse and recycling — while reducing environmental impact and building resilient economies.","applications":[{"title":"Product design","description":"Designing for repair, disassembly and recycling."},{"title":"Cities","description":"Managing water, waste and construction materials."},{"title":"Business","description":"New models such as leasing, sharing and remanufacturing."},{"title":"Critical minerals","description":"Securing the materials needed for clean technologies."}],"whyItMatters":["Global material use has grown rapidly and continues to rise.","Circular approaches can reduce emissions, pollution and costs together.","Every learner can apply circular thinking at home, at school and in their future careers."],"outcomes":["Map the life cycle of an everyday product.","Compare linear and circular economic models.","Analyse resource consumption data.","Redesign a product using circular principles."],"foundationalKnowledge":["Percentages","Reading charts","Basic materials knowledge","Systems thinking"],"prerequisites":[{"title":"Materials and their properties","why":"Different materials can be recovered in different ways.","categorySlug":"science-discovery"},{"title":"How economies work","why":"Circularity changes how value is created.","categorySlug":"economics"},{"title":"Design thinking","why":"Circular solutions start at the design stage.","categorySlug":"innovation-design"}],"stages":[{"id":"su-s1","academy":"Foundation","title":"Where things come from","summary":"Raw materials, products and waste from first principles.","weeks":3},{"id":"su-s2","academy":"Advanced","title":"Measuring impact","summary":"Life-cycle assessment and material flow analysis.","weeks":5},{"id":"su-s3","academy":"Elite Mastery","title":"Designing circular systems","summary":"Circular business models, policy and a redesign project.","weeks":4}],"durationLabel":"About 12 weeks at 4 hours per week","relatedCategorySlug":"innovation-design","curriculum":{"referenceInstitution":"Illustrative reference — generic undergraduate unit structure","referenceUnitTitle":"Circular Economy and Sustainable Engineering","referenceUnitCode":"SUS-105 (illustrative)","isIllustrative":true,"description":"Principles of sustainable resource management, life-cycle assessment and circular design, applied through data analysis and a product redesign project.","outcomes":["Describe global material flows and their impacts.","Conduct a simplified life-cycle assessment.","Apply circular design strategies to a product.","Evaluate policy and business approaches to circularity."],"prerequisites":["Basic mathematics","Introductory science"],"modules":[{"id":"su-m1","number":1,"title":"Resources and Society","summary":"How humanity uses Earth’s materials.","weeks":"Week 1","topics":[{"id":"su-m1-t1","title":"Renewable vs non-renewable resources","source":"edumate","durationMins":15},{"id":"su-m1-t2","title":"Global material use","source":"edumate","durationMins":20},{"id":"su-m1-t3","title":"Planetary boundaries","source":"edumate","durationMins":12}],"lectureRefs":[],"readings":["irp-outlook","our-world-in-data"]},{"id":"su-m2","number":2,"title":"The Linear Economy","summary":"Take, make, waste — and its costs.","weeks":"Week 2","topics":[{"id":"su-m2-t1","title":"Extraction and processing","source":"edumate","durationMins":20},{"id":"su-m2-t2","title":"Waste and pollution","source":"edumate","durationMins":12},{"id":"su-m2-t3","title":"Hidden environmental costs","source":"edumate","durationMins":10}],"lectureRefs":[],"readings":["emf-circular"]},{"id":"su-m3","number":3,"title":"Circular Principles","summary":"Designing waste out of the system.","weeks":"Week 3–4","topics":[{"id":"su-m3-t1","title":"The butterfly diagram","source":"reference","durationMins":12},{"id":"su-m3-t2","title":"Reduce, reuse, repair, recycle","source":"edumate","durationMins":10},{"id":"su-m3-t3","title":"Biological and technical cycles","source":"edumate","durationMins":15}],"lectureRefs":[],"readings":["emf-circular"]},{"id":"su-m4","number":4,"title":"Life-Cycle Assessment","summary":"Measuring impact from cradle to grave.","weeks":"Week 5–6","topics":[{"id":"su-m4-t1","title":"System boundaries","source":"edumate","durationMins":10},{"id":"su-m4-t2","title":"Impact categories","source":"reference","durationMins":15},{"id":"su-m4-t3","title":"Interpreting results","source":"edumate","durationMins":20}],"lectureRefs":[],"readings":["openstax-chemistry-2e"]},{"id":"su-m5","number":5,"title":"Material Flow Analysis","summary":"Following materials through the economy.","weeks":"Week 7","topics":[{"id":"su-m5-t1","title":"Stocks and flows","source":"edumate","durationMins":15},{"id":"su-m5-t2","title":"Data sources","source":"edumate","durationMins":20},{"id":"su-m5-t3","title":"Building a flow diagram","source":"edumate","durationMins":12}],"lectureRefs":[],"readings":["our-world-in-data"],"practicalId":"lab-resource-analysis"},{"id":"su-m6","number":6,"title":"Circular Design","summary":"Products built to last and to be remade.","weeks":"Week 8–9","topics":[{"id":"su-m6-t1","title":"Design for disassembly","source":"edumate","durationMins":20},{"id":"su-m6-t2","title":"Material selection","source":"edumate","durationMins":12},{"id":"su-m6-t3","title":"Remanufacturing","source":"edumate","durationMins":10}],"lectureRefs":[],"readings":[]},{"id":"su-m7","number":7,"title":"Business and Policy","summary":"Systems that make circularity work.","weeks":"Week 10–11","topics":[{"id":"su-m7-t1","title":"Product-as-a-service","source":"edumate","durationMins":12},{"id":"su-m7-t2","title":"Extended producer responsibility","source":"edumate","durationMins":10},{"id":"su-m7-t3","title":"Critical minerals","source":"edumate","durationMins":15}],"lectureRefs":[],"readings":["irp-outlook"]},{"id":"su-m8","number":8,"title":"Circular Redesign Project","summary":"Redesign an everyday product.","weeks":"Week 12","topics":[{"id":"su-m8-t1","title":"Choosing a product","source":"edumate","durationMins":10},{"id":"su-m8-t2","title":"Applying circular strategies","source":"edumate","durationMins":15},{"id":"su-m8-t3","title":"Presenting the impact","source":"edumate","durationMins":20}],"lectureRefs":[],"readings":[],"practicalId":"lab-product-redesign"}],"assessments":[{"title":"Module mastery checks","type":"Mastery quiz","weight":30,"description":"Adaptive verification of each module."},{"title":"Resource consumption analysis","type":"Practical","weight":25,"description":"Analyse real consumption data."},{"title":"Life-cycle explanation","type":"Written explanation","weight":15,"description":"Explain the life cycle of a product you own."},{"title":"Circular redesign","type":"Project","weight":30,"description":"Redesign a product and estimate its impact."}],"furtherStudy":["emf-circular","irp-outlook","without-hot-air"]}}'::jsonb, 4) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, description = excluded.description, discipline = excluded.discipline, difficulty = excluded.difficulty, motif = excluded.motif, theme = excluded.theme, status = excluded.status, tags = excluded.tags, featured = excluded.featured, trending = excluded.trending, emerging = excluded.emerging, beginner_friendly = excluded.beginner_friendly, university_level = excluded.university_level, added_at = excluded.added_at, estimated_hours = excluded.estimated_hours, learners_exploring = excluded.learners_exploring, detail = excluded.detail, sort_order = excluded.sort_order;
insert into public.explore_subjects (slug, title, tagline, description, discipline, difficulty, motif, theme, status, tags, featured, trending, emerging, beginner_friendly, university_level, added_at, estimated_hours, learners_exploring, detail, sort_order) values ('aerospace-engineering', 'Aerospace Engineering', 'From flight to orbit.', 'Discover how aircraft fly and spacecraft reach orbit — aerodynamics, propulsion and orbital mechanics.', 'Engineering', 'advanced', 'rocket', '{"base":"#1e293b","accent":"#fb923c","tint":"#ffedd5","ink":"#c2410c"}'::jsonb, 'coming-soon', array['Aerodynamics', 'Propulsion', 'Orbits']::text[], true, false, true, false, true, '2026-11-18', 70, 1540, '{"introduction":"Aerospace engineering covers the design of aircraft and spacecraft. A full EduMate pathway is being developed.","applications":[{"title":"Aviation","description":"Efficient, quieter and lower-emission aircraft."},{"title":"Space","description":"Satellites, launch vehicles and exploration missions."}],"whyItMatters":["Space and aviation connect the world and expand scientific knowledge."],"outcomes":["Explain lift, drag, thrust and weight.","Describe how orbits work."],"foundationalKnowledge":["Forces and motion","Basic trigonometry"],"prerequisites":[{"title":"Forces & motion","why":"Flight is applied mechanics.","categorySlug":"science-discovery"}],"relatedCategorySlug":"science-discovery","curriculum":null,"stages":[],"durationLabel":"Pathway in development"}'::jsonb, 5) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, description = excluded.description, discipline = excluded.discipline, difficulty = excluded.difficulty, motif = excluded.motif, theme = excluded.theme, status = excluded.status, tags = excluded.tags, featured = excluded.featured, trending = excluded.trending, emerging = excluded.emerging, beginner_friendly = excluded.beginner_friendly, university_level = excluded.university_level, added_at = excluded.added_at, estimated_hours = excluded.estimated_hours, learners_exploring = excluded.learners_exploring, detail = excluded.detail, sort_order = excluded.sort_order;
insert into public.explore_subjects (slug, title, tagline, description, discipline, difficulty, motif, theme, status, tags, featured, trending, emerging, beginner_friendly, university_level, added_at, estimated_hours, learners_exploring, detail, sort_order) values ('biotechnology', 'Biotechnology', 'Engineering with living systems.', 'Explore how scientists use cells, DNA and enzymes to create medicines, materials and sustainable food.', 'Life Sciences', 'intermediate', 'dna', '{"base":"#831843","accent":"#f9a8d4","tint":"#fce7f3","ink":"#be185d"}'::jsonb, 'coming-soon', array['Genetics', 'Medicine', 'Bioprocessing']::text[], true, true, false, true, false, '2026-11-16', 60, 2050, '{"introduction":"Biotechnology harnesses biology to solve problems in health, food and industry. A full pathway is being developed.","applications":[{"title":"Medicine","description":"Vaccines, gene therapies and biologic drugs."},{"title":"Food","description":"Resilient crops and alternative proteins."}],"whyItMatters":["Biotechnology is transforming healthcare and agriculture."],"outcomes":["Explain how DNA encodes information.","Describe key biotechnology techniques."],"foundationalKnowledge":["Cells","Basic chemistry"],"prerequisites":[{"title":"Cells and life","why":"All biotechnology builds on cell biology.","categorySlug":"science-discovery"}],"relatedCategorySlug":"science-discovery","curriculum":null,"stages":[],"durationLabel":"Pathway in development"}'::jsonb, 6) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, description = excluded.description, discipline = excluded.discipline, difficulty = excluded.difficulty, motif = excluded.motif, theme = excluded.theme, status = excluded.status, tags = excluded.tags, featured = excluded.featured, trending = excluded.trending, emerging = excluded.emerging, beginner_friendly = excluded.beginner_friendly, university_level = excluded.university_level, added_at = excluded.added_at, estimated_hours = excluded.estimated_hours, learners_exploring = excluded.learners_exploring, detail = excluded.detail, sort_order = excluded.sort_order;
insert into public.explore_subjects (slug, title, tagline, description, discipline, difficulty, motif, theme, status, tags, featured, trending, emerging, beginner_friendly, university_level, added_at, estimated_hours, learners_exploring, detail, sort_order) values ('quantum-computing', 'Quantum Computing', 'Computing with the rules of the very small.', 'Meet qubits, superposition and entanglement, and discover what quantum computers may one day solve.', 'Computing', 'university', 'qubit', '{"base":"#312e81","accent":"#a5b4fc","tint":"#e0e7ff","ink":"#4338ca"}'::jsonb, 'coming-soon', array['Qubits', 'Algorithms', 'Physics']::text[], true, false, true, false, true, '2026-11-12', 80, 1880, '{"introduction":"Quantum computing uses quantum mechanics to process information in new ways. A full pathway is being developed.","applications":[{"title":"Chemistry","description":"Simulating molecules for new materials and medicines."},{"title":"Security","description":"New cryptography for a quantum era."}],"whyItMatters":["Quantum technologies may reshape computing, sensing and security."],"outcomes":["Describe a qubit and superposition.","Explain a simple quantum circuit."],"foundationalKnowledge":["Probability","Vectors"],"prerequisites":[{"title":"Probability basics","why":"Quantum measurement is probabilistic.","categorySlug":"science-discovery"}],"relatedCategorySlug":"science-discovery","curriculum":null,"stages":[],"durationLabel":"Pathway in development"}'::jsonb, 7) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, description = excluded.description, discipline = excluded.discipline, difficulty = excluded.difficulty, motif = excluded.motif, theme = excluded.theme, status = excluded.status, tags = excluded.tags, featured = excluded.featured, trending = excluded.trending, emerging = excluded.emerging, beginner_friendly = excluded.beginner_friendly, university_level = excluded.university_level, added_at = excluded.added_at, estimated_hours = excluded.estimated_hours, learners_exploring = excluded.learners_exploring, detail = excluded.detail, sort_order = excluded.sort_order;
insert into public.explore_subjects (slug, title, tagline, description, discipline, difficulty, motif, theme, status, tags, featured, trending, emerging, beginner_friendly, university_level, added_at, estimated_hours, learners_exploring, detail, sort_order) values ('advanced-materials-science', 'Advanced Materials Science', 'Atoms arranged for extraordinary properties.', 'Discover graphene, superalloys and smart materials — and how structure at the atomic scale shapes the world we build.', 'Physical Sciences', 'advanced', 'lattice', '{"base":"#134e4a","accent":"#5eead4","tint":"#ccfbf1","ink":"#0f766e"}'::jsonb, 'coming-soon', array['Nanomaterials', 'Crystals', 'Composites']::text[], true, false, false, false, true, '2026-11-08', 62, 1320, '{"introduction":"Materials science links atomic structure to real-world properties. A full pathway is being developed.","applications":[{"title":"Electronics","description":"New materials for faster, cooler devices."},{"title":"Transport","description":"Lighter, stronger composites for vehicles."}],"whyItMatters":["Almost every technological advance depends on better materials."],"outcomes":["Relate structure to properties.","Describe classes of advanced materials."],"foundationalKnowledge":["Atoms and bonding"],"prerequisites":[{"title":"Atoms and bonding","why":"Structure determines properties.","categorySlug":"science-discovery"}],"relatedCategorySlug":"manufacturing","curriculum":null,"stages":[],"durationLabel":"Pathway in development"}'::jsonb, 8) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, description = excluded.description, discipline = excluded.discipline, difficulty = excluded.difficulty, motif = excluded.motif, theme = excluded.theme, status = excluded.status, tags = excluded.tags, featured = excluded.featured, trending = excluded.trending, emerging = excluded.emerging, beginner_friendly = excluded.beginner_friendly, university_level = excluded.university_level, added_at = excluded.added_at, estimated_hours = excluded.estimated_hours, learners_exploring = excluded.learners_exploring, detail = excluded.detail, sort_order = excluded.sort_order;
insert into public.explore_lab_projects (id, subject_slug, title, type, difficulty, duration_mins, summary, objectives, steps, criteria, deliverable, simulation, sort_order) values ('lab-robot-arm', 'robotics-autonomous-systems', 'Simulate a robotic arm', 'simulation', 'intermediate', 45, 'Control a two-joint robotic arm and discover how joint angles determine where the gripper ends up.', '["Relate joint angles to end-effector position.","Apply forward kinematics using trigonometry.","Identify the arm’s reachable workspace."]'::jsonb, '[{"id":"lab-robot-arm-step1","title":"Explore the arm","detail":"Move each joint slider and observe how the gripper moves."},{"id":"lab-robot-arm-step2","title":"Predict a position","detail":"Pick two angles and calculate the gripper position by hand."},{"id":"lab-robot-arm-step3","title":"Check your prediction","detail":"Set the angles in the simulation and compare."},{"id":"lab-robot-arm-step4","title":"Map the workspace","detail":"Find the furthest and closest points the arm can reach."}]'::jsonb, '[{"criterion":"Understanding","weight":30,"description":"Accurately explains the kinematics concepts involved."},{"criterion":"Method","weight":30,"description":"Follows a clear, repeatable process and records observations."},{"criterion":"Analysis","weight":25,"description":"Interprets results and identifies limitations."},{"criterion":"Communication","weight":15,"description":"Presents findings clearly in their own words."}]'::jsonb, 'A short report with your calculations, simulation screenshots and workspace sketch.', 'robot-arm', 0) on conflict (id) do update set subject_slug = excluded.subject_slug, title = excluded.title, type = excluded.type, difficulty = excluded.difficulty, duration_mins = excluded.duration_mins, summary = excluded.summary, objectives = excluded.objectives, steps = excluded.steps, criteria = excluded.criteria, deliverable = excluded.deliverable, simulation = excluded.simulation, sort_order = excluded.sort_order;
insert into public.explore_lab_projects (id, subject_slug, title, type, difficulty, duration_mins, summary, objectives, steps, criteria, deliverable, simulation, sort_order) values ('lab-line-follower', 'robotics-autonomous-systems', 'Design a line-following robot', 'project', 'advanced', 180, 'Design the sensing and control logic for a robot that follows a track autonomously.', '["Select appropriate sensors for line detection.","Design a feedback controller.","Test and tune behaviour iteratively."]'::jsonb, '[{"id":"lab-line-follower-step1","title":"Define requirements","detail":"Describe the track, speed and accuracy you are aiming for."},{"id":"lab-line-follower-step2","title":"Choose sensors","detail":"Justify your choice of sensors and their placement."},{"id":"lab-line-follower-step3","title":"Write control logic","detail":"Write pseudocode for steering based on sensor readings."},{"id":"lab-line-follower-step4","title":"Test and tune","detail":"Describe how you would test and improve the controller."},{"id":"lab-line-follower-step5","title":"Present","detail":"Summarise your design and what you learned."}]'::jsonb, '[{"criterion":"Understanding","weight":30,"description":"Accurately explains the control and sensing concepts involved."},{"criterion":"Method","weight":30,"description":"Follows a clear, repeatable process and records observations."},{"criterion":"Analysis","weight":25,"description":"Interprets results and identifies limitations."},{"criterion":"Communication","weight":15,"description":"Presents findings clearly in their own words."}]'::jsonb, 'Design document with diagrams, pseudocode and a test plan.', null, 1) on conflict (id) do update set subject_slug = excluded.subject_slug, title = excluded.title, type = excluded.type, difficulty = excluded.difficulty, duration_mins = excluded.duration_mins, summary = excluded.summary, objectives = excluded.objectives, steps = excluded.steps, criteria = excluded.criteria, deliverable = excluded.deliverable, simulation = excluded.simulation, sort_order = excluded.sort_order;
insert into public.explore_lab_projects (id, subject_slug, title, type, difficulty, duration_mins, summary, objectives, steps, criteria, deliverable, simulation, sort_order) values ('lab-circuit-basics', 'robotics-autonomous-systems', 'Simulate a simple electronic circuit', 'experiment', 'beginner', 30, 'Build a virtual circuit and explore how voltage, current and resistance relate.', '["Apply Ohm’s law.","Measure current in a series circuit.","Explain the role of a resistor."]'::jsonb, '[{"id":"lab-circuit-basics-step1","title":"Set the voltage","detail":"Choose a supply voltage for your circuit."},{"id":"lab-circuit-basics-step2","title":"Change resistance","detail":"Adjust the resistor and observe the current."},{"id":"lab-circuit-basics-step3","title":"Record results","detail":"Note at least five voltage–current readings."},{"id":"lab-circuit-basics-step4","title":"Draw conclusions","detail":"Explain the relationship you observed."}]'::jsonb, '[{"criterion":"Understanding","weight":30,"description":"Accurately explains the circuit concepts involved."},{"criterion":"Method","weight":30,"description":"Follows a clear, repeatable process and records observations."},{"criterion":"Analysis","weight":25,"description":"Interprets results and identifies limitations."},{"criterion":"Communication","weight":15,"description":"Presents findings clearly in their own words."}]'::jsonb, 'A table of readings and a one-paragraph explanation of Ohm’s law.', 'circuit', 2) on conflict (id) do update set subject_slug = excluded.subject_slug, title = excluded.title, type = excluded.type, difficulty = excluded.difficulty, duration_mins = excluded.duration_mins, summary = excluded.summary, objectives = excluded.objectives, steps = excluded.steps, criteria = excluded.criteria, deliverable = excluded.deliverable, simulation = excluded.simulation, sort_order = excluded.sort_order;
insert into public.explore_lab_projects (id, subject_slug, title, type, difficulty, duration_mins, summary, objectives, steps, criteria, deliverable, simulation, sort_order) values ('lab-neural-network', 'artificial-intelligence-machine-learning', 'Build a basic neural network', 'coding', 'intermediate', 90, 'Train a tiny neural network to separate two classes of points and watch it learn.', '["Describe the structure of a neural network.","Explain how training reduces error.","Recognise underfitting and overfitting."]'::jsonb, '[{"id":"lab-neural-network-step1","title":"Inspect the data","detail":"Look at the two classes of points you will separate."},{"id":"lab-neural-network-step2","title":"Configure the network","detail":"Choose the number of hidden units."},{"id":"lab-neural-network-step3","title":"Train","detail":"Run training and watch the loss decrease."},{"id":"lab-neural-network-step4","title":"Evaluate","detail":"Record accuracy and describe the decision boundary."}]'::jsonb, '[{"criterion":"Understanding","weight":30,"description":"Accurately explains the neural network concepts involved."},{"criterion":"Method","weight":30,"description":"Follows a clear, repeatable process and records observations."},{"criterion":"Analysis","weight":25,"description":"Interprets results and identifies limitations."},{"criterion":"Communication","weight":15,"description":"Presents findings clearly in their own words."}]'::jsonb, 'Your final configuration, accuracy and a short reflection on what the network learned.', 'neural-net', 3) on conflict (id) do update set subject_slug = excluded.subject_slug, title = excluded.title, type = excluded.type, difficulty = excluded.difficulty, duration_mins = excluded.duration_mins, summary = excluded.summary, objectives = excluded.objectives, steps = excluded.steps, criteria = excluded.criteria, deliverable = excluded.deliverable, simulation = excluded.simulation, sort_order = excluded.sort_order;
insert into public.explore_lab_projects (id, subject_slug, title, type, difficulty, duration_mins, summary, objectives, steps, criteria, deliverable, simulation, sort_order) values ('lab-image-classifier', 'artificial-intelligence-machine-learning', 'Responsible image classifier', 'project', 'advanced', 240, 'Plan an image classification project on an open dataset and evaluate it for fairness.', '["Prepare a dataset.","Train and evaluate a model.","Identify sources of bias."]'::jsonb, '[{"id":"lab-image-classifier-step1","title":"Choose a dataset","detail":"Select an open dataset and describe its contents."},{"id":"lab-image-classifier-step2","title":"Plan the model","detail":"Describe the model you will train and why."},{"id":"lab-image-classifier-step3","title":"Evaluate","detail":"Describe the metrics you will use."},{"id":"lab-image-classifier-step4","title":"Assess fairness","detail":"Identify who could be affected by errors."}]'::jsonb, '[{"criterion":"Understanding","weight":30,"description":"Accurately explains the machine learning concepts involved."},{"criterion":"Method","weight":30,"description":"Follows a clear, repeatable process and records observations."},{"criterion":"Analysis","weight":25,"description":"Interprets results and identifies limitations."},{"criterion":"Communication","weight":15,"description":"Presents findings clearly in their own words."}]'::jsonb, 'Project plan, evaluation approach and a fairness assessment.', null, 4) on conflict (id) do update set subject_slug = excluded.subject_slug, title = excluded.title, type = excluded.type, difficulty = excluded.difficulty, duration_mins = excluded.duration_mins, summary = excluded.summary, objectives = excluded.objectives, steps = excluded.steps, criteria = excluded.criteria, deliverable = excluded.deliverable, simulation = excluded.simulation, sort_order = excluded.sort_order;
insert into public.explore_lab_projects (id, subject_slug, title, type, difficulty, duration_mins, summary, objectives, steps, criteria, deliverable, simulation, sort_order) values ('lab-battery-model', 'energy-generation-storage', 'Model battery charging and discharging', 'simulation', 'beginner', 40, 'Explore how a battery’s state of charge changes with current and time.', '["Relate capacity, current and time.","Compare charging and discharging curves.","Explain why fast charging slows near full."]'::jsonb, '[{"id":"lab-battery-model-step1","title":"Set the current","detail":"Choose a charging current using the slider."},{"id":"lab-battery-model-step2","title":"Observe the curve","detail":"Watch how state of charge changes over time."},{"id":"lab-battery-model-step3","title":"Compare rates","detail":"Try three different currents and record the time to 80%."},{"id":"lab-battery-model-step4","title":"Explain","detail":"Describe why the curve flattens near 100%."}]'::jsonb, '[{"criterion":"Understanding","weight":30,"description":"Accurately explains the battery concepts involved."},{"criterion":"Method","weight":30,"description":"Follows a clear, repeatable process and records observations."},{"criterion":"Analysis","weight":25,"description":"Interprets results and identifies limitations."},{"criterion":"Communication","weight":15,"description":"Presents findings clearly in their own words."}]'::jsonb, 'Charging times for three currents and a written explanation.', 'battery', 5) on conflict (id) do update set subject_slug = excluded.subject_slug, title = excluded.title, type = excluded.type, difficulty = excluded.difficulty, duration_mins = excluded.duration_mins, summary = excluded.summary, objectives = excluded.objectives, steps = excluded.steps, criteria = excluded.criteria, deliverable = excluded.deliverable, simulation = excluded.simulation, sort_order = excluded.sort_order;
insert into public.explore_lab_projects (id, subject_slug, title, type, difficulty, duration_mins, summary, objectives, steps, criteria, deliverable, simulation, sort_order) values ('lab-microgrid', 'energy-generation-storage', 'Design a community microgrid', 'challenge', 'advanced', 150, 'Size solar panels and battery storage to power a small community through the night.', '["Analyse a demand profile.","Size generation and storage.","Justify trade-offs."]'::jsonb, '[{"id":"lab-microgrid-step1","title":"Understand demand","detail":"Estimate daily energy use for 50 homes."},{"id":"lab-microgrid-step2","title":"Size solar","detail":"Calculate the solar capacity needed."},{"id":"lab-microgrid-step3","title":"Size storage","detail":"Calculate battery capacity for overnight use."},{"id":"lab-microgrid-step4","title":"Justify","detail":"Explain cost, reliability and environmental trade-offs."}]'::jsonb, '[{"criterion":"Understanding","weight":30,"description":"Accurately explains the energy system concepts involved."},{"criterion":"Method","weight":30,"description":"Follows a clear, repeatable process and records observations."},{"criterion":"Analysis","weight":25,"description":"Interprets results and identifies limitations."},{"criterion":"Communication","weight":15,"description":"Presents findings clearly in their own words."}]'::jsonb, 'Sizing calculations and a one-page design justification.', null, 6) on conflict (id) do update set subject_slug = excluded.subject_slug, title = excluded.title, type = excluded.type, difficulty = excluded.difficulty, duration_mins = excluded.duration_mins, summary = excluded.summary, objectives = excluded.objectives, steps = excluded.steps, criteria = excluded.criteria, deliverable = excluded.deliverable, simulation = excluded.simulation, sort_order = excluded.sort_order;
insert into public.explore_lab_projects (id, subject_slug, title, type, difficulty, duration_mins, summary, objectives, steps, criteria, deliverable, simulation, sort_order) values ('lab-transistor-switch', 'semiconductors-chip-manufacturing', 'Explore transistor switching', 'simulation', 'intermediate', 35, 'Change a transistor’s gate voltage and see when it switches on.', '["Identify the threshold voltage.","Explain on and off states.","Relate switching to digital logic."]'::jsonb, '[{"id":"lab-transistor-switch-step1","title":"Sweep the gate voltage","detail":"Slowly increase the gate voltage."},{"id":"lab-transistor-switch-step2","title":"Find the threshold","detail":"Note where current starts to flow."},{"id":"lab-transistor-switch-step3","title":"Connect to logic","detail":"Explain how this creates a 0 or 1."}]'::jsonb, '[{"criterion":"Understanding","weight":30,"description":"Accurately explains the transistor concepts involved."},{"criterion":"Method","weight":30,"description":"Follows a clear, repeatable process and records observations."},{"criterion":"Analysis","weight":25,"description":"Interprets results and identifies limitations."},{"criterion":"Communication","weight":15,"description":"Presents findings clearly in their own words."}]'::jsonb, 'Threshold measurement and an explanation of switching.', 'transistor', 7) on conflict (id) do update set subject_slug = excluded.subject_slug, title = excluded.title, type = excluded.type, difficulty = excluded.difficulty, duration_mins = excluded.duration_mins, summary = excluded.summary, objectives = excluded.objectives, steps = excluded.steps, criteria = excluded.criteria, deliverable = excluded.deliverable, simulation = excluded.simulation, sort_order = excluded.sort_order;
insert into public.explore_lab_projects (id, subject_slug, title, type, difficulty, duration_mins, summary, objectives, steps, criteria, deliverable, simulation, sort_order) values ('lab-resource-analysis', 'sustainable-resources-circular-engineering', 'Analyse sustainable resource consumption', 'experiment', 'beginner', 50, 'Compare how recycling rates change the raw material needed to make a product.', '["Read resource data.","Calculate material savings.","Recommend improvements."]'::jsonb, '[{"id":"lab-resource-analysis-step1","title":"Pick a material","detail":"Choose aluminium, plastic or glass."},{"id":"lab-resource-analysis-step2","title":"Adjust recycling rate","detail":"See how virgin material demand changes."},{"id":"lab-resource-analysis-step3","title":"Calculate savings","detail":"Record savings at three recycling rates."},{"id":"lab-resource-analysis-step4","title":"Recommend","detail":"Suggest one realistic action to improve recycling."}]'::jsonb, '[{"criterion":"Understanding","weight":30,"description":"Accurately explains the resource concepts involved."},{"criterion":"Method","weight":30,"description":"Follows a clear, repeatable process and records observations."},{"criterion":"Analysis","weight":25,"description":"Interprets results and identifies limitations."},{"criterion":"Communication","weight":15,"description":"Presents findings clearly in their own words."}]'::jsonb, 'Savings table and a recommendation paragraph.', 'resources', 8) on conflict (id) do update set subject_slug = excluded.subject_slug, title = excluded.title, type = excluded.type, difficulty = excluded.difficulty, duration_mins = excluded.duration_mins, summary = excluded.summary, objectives = excluded.objectives, steps = excluded.steps, criteria = excluded.criteria, deliverable = excluded.deliverable, simulation = excluded.simulation, sort_order = excluded.sort_order;
insert into public.explore_lab_projects (id, subject_slug, title, type, difficulty, duration_mins, summary, objectives, steps, criteria, deliverable, simulation, sort_order) values ('lab-product-redesign', 'sustainable-resources-circular-engineering', 'Circular product redesign', 'project', 'intermediate', 180, 'Redesign an everyday product so it can be repaired, reused and recycled.', '["Map a product life cycle.","Apply circular strategies.","Estimate impact reduction."]'::jsonb, '[{"id":"lab-product-redesign-step1","title":"Choose a product","detail":"Pick an everyday item and map its life cycle."},{"id":"lab-product-redesign-step2","title":"Find hotspots","detail":"Identify where most waste or impact occurs."},{"id":"lab-product-redesign-step3","title":"Redesign","detail":"Apply at least two circular strategies."},{"id":"lab-product-redesign-step4","title":"Present","detail":"Explain the expected improvement."}]'::jsonb, '[{"criterion":"Understanding","weight":30,"description":"Accurately explains the circular design concepts involved."},{"criterion":"Method","weight":30,"description":"Follows a clear, repeatable process and records observations."},{"criterion":"Analysis","weight":25,"description":"Interprets results and identifies limitations."},{"criterion":"Communication","weight":15,"description":"Presents findings clearly in their own words."}]'::jsonb, 'Life-cycle map, redesign sketch and impact explanation.', null, 9) on conflict (id) do update set subject_slug = excluded.subject_slug, title = excluded.title, type = excluded.type, difficulty = excluded.difficulty, duration_mins = excluded.duration_mins, summary = excluded.summary, objectives = excluded.objectives, steps = excluded.steps, criteria = excluded.criteria, deliverable = excluded.deliverable, simulation = excluded.simulation, sort_order = excluded.sort_order;
