insert into public.explore_community_posts (id, kind, title, excerpt, author_display, author_band, region, subject_slug, achievement, moderation, base_appreciations, replies, created_at) values ('post-1', 'showcase', 'My two-joint arm reaches every point on the table', 'I mapped the full workspace of the simulated arm and found the dead zone near the base. Here is how I worked it out with trigonometry.', 'Amara K.', '16–18', 'Africa', 'robotics-autonomous-systems', 'Robotics — Advanced stage complete', 'reviewed', 142, 18, '2026-11-17') on conflict (id) do nothing;
insert into public.explore_community_posts (id, kind, title, excerpt, author_display, author_band, region, subject_slug, achievement, moderation, base_appreciations, replies, created_at) values ('post-2', 'explanation', 'Backpropagation explained with a recipe analogy', 'If a cake tastes wrong, you work backwards to find which ingredient caused it. That’s basically how a network learns.', 'Leo M.', 'Under 16', 'Europe', 'artificial-intelligence-machine-learning', 'Top explainer this month', 'reviewed', 311, 42, '2026-11-16') on conflict (id) do nothing;
